#include<bits/stdc++.h>
using namespace std;

int similar(char a[],char b[]){
    int ret=0;
    for(int i=0;i<4;++i)
        ret+=(a[i]==b[i]);
    return ret;
}

int n,cnt[100+5];
char s[100+5][4];

bool is_ok(int x){
    char tmp[4];
    sprintf(tmp,"%04d",x); // 补前导 0，保证与线索一样是 4 位
    for(int i=0;i<n;++i)
        if(similar(tmp,s[i])!=cnt[i])return false;
    return true;
}

int main(){
    cin>>n;
    for(int i=0;i<n;++i)
        cin>>s[i]>>cnt[i];
    for(int i=0;i<10000;++i)
        if(is_ok(i)){
            printf("%04d",i);
            return 0;
        }
    cout<<-1;
    return 0;
}
